<?php
$pdo=db();$canReview=in_array($user['role'],['Administrator','Head'],true);$q=trim((string)($_GET['q']??''));$filterStatus=(string)($_GET['status']??'');$filterYear=filter_var($_GET['year']??null,FILTER_VALIDATE_INT);$new=isset($_GET['new']);$terms=[];$classes=[];$applications=[];$history=[];$stats=[];
try{$terms=$pdo->query('SELECT id,academic_year,term_number,name,starts_on,ends_on FROM school_terms ORDER BY academic_year DESC,term_number DESC')->fetchAll();$classes=$pdo->query('SELECT form_level,stream,academic_year FROM class_groups ORDER BY academic_year DESC,form_level,stream')->fetchAll();$stats=$pdo->query('SELECT status,COUNT(*) AS total FROM admission_applications GROUP BY status')->fetchAll();$where=[];$params=[];if($q!==''){$like='%'.$q.'%';$where[]='(application_code LIKE :code OR first_name LIKE :first OR last_name LIKE :last OR guardian_name LIKE :guardian)';$params=['code'=>$like,'first'=>$like,'last'=>$like,'guardian'=>$like];}if(in_array($filterStatus,['Submitted','Under Review','Waitlisted','Offered','Accepted','Declined','Enrolled'],true)){$where[]='status=:status';$params['status']=$filterStatus;}if($filterYear&&$filterYear>=2000&&$filterYear<=2100){$where[]='entry_year=:year';$params['year']=$filterYear;}$sql='SELECT * FROM admission_applications';if($where)$sql.=' WHERE '.implode(' AND ',$where);$sql.=' ORDER BY FIELD(status,\'Submitted\',\'Under Review\',\'Waitlisted\',\'Offered\',\'Accepted\',\'Declined\',\'Enrolled\'),entry_year,last_name,first_name LIMIT 200';$stmt=$pdo->prepare($sql);$stmt->execute($params);$applications=$stmt->fetchAll();if($applications){$ids=array_map('intval',array_column($applications,'id'));$in=implode(',',array_fill(0,count($ids),'?'));$hs=$pdo->prepare("SELECT application_id,from_status,to_status,notes,created_at,u.full_name FROM admission_status_history h LEFT JOIN users u ON u.id=h.changed_by WHERE application_id IN ($in) ORDER BY h.created_at DESC,h.id DESC");$hs->execute($ids);foreach($hs->fetchAll() as $h)$history[$h['application_id']][]=$h;}}catch(Throwable $e){error_log('Admissions page failed: '.$e->getMessage());echo '<section class="panel settings-panel"><h1>Admissions setup required</h1><p>An administrator should import <code>database/migrations/012_admissions.sql</code> into the school database, then reload this page.</p></section>';return;}
$statsByStatus=[];foreach($stats as $s)$statsByStatus[$s['status']]=(int)$s['total'];$currentYear=(int)date('Y');$termYears=array_values(array_unique(array_merge(array_map(fn($t)=>(int)$t['academic_year'],$terms),[$currentYear])));
?>
<div class="page-heading"><div><div class="eyebrow">LEARNER INTAKE</div><h1>Admissions</h1><p class="subheading">Track applications from initial review through offer acceptance and learner enrollment.</p></div><a class="primary-button" href="?page=admissions&new=1">＋ New application</a></div>
<section class="stat-strip"><div><span>Submitted</span><b><?= number_format($statsByStatus['Submitted']??0) ?></b></div><div><span>Under review</span><b><?= number_format($statsByStatus['Under Review']??0) ?></b></div><div><span>Offers / accepted</span><b><?= number_format(($statsByStatus['Offered']??0)+($statsByStatus['Accepted']??0)) ?></b></div><div><span>Enrolled</span><b><?= number_format($statsByStatus['Enrolled']??0) ?></b></div></section>
<?php if($new): ?><section class="panel settings-panel"><div class="panel-heading"><div><h2>Register an application</h2><p>Admission number is assigned only when an accepted application is enrolled.</p></div></div><form method="post" action="actions/admission_submit.php" class="student-form"><?= csrf_field() ?><div class="form-section-title">Applicant</div><div class="form-grid"><label>First name<input name="first_name" required maxlength="80"></label><label>Last name<input name="last_name" required maxlength="80"></label><label>Sex<select name="sex" required><option value="">Select</option><option value="F">Female</option><option value="M">Male</option></select></label><label>Date of birth <span class="optional">Optional</span><input type="date" name="date_of_birth" max="<?= h(date('Y-m-d')) ?>"></label><label>National ID <span class="optional">Optional</span><input name="national_id" maxlength="30"></label><label>Intended form<select name="intended_form" required><?php for($f=1;$f<=6;$f++): ?><option value="<?= $f ?>">Form <?= $f ?><?= $f<=4?' · O-Level':' · A-Level' ?></option><?php endfor; ?></select></label><label>Entry academic year<input type="number" name="entry_year" min="<?= $currentYear ?>" max="2100" value="<?= $currentYear ?>" required></label><label>Preferred stream <span class="optional">Optional</span><input name="stream_preference" maxlength="20"></label><label>Previous school <span class="optional">Optional</span><input name="previous_school" maxlength="180"></label></div><div class="form-section-title guardian-title">Parent / legal guardian contact</div><div class="form-grid"><label>Guardian name<input name="guardian_name" required maxlength="160"></label><label>Relationship<select name="guardian_relationship" required><option value="">Select</option><?php foreach(['Parent','Legal guardian','Grandparent','Other relative','Other'] as $r): ?><option><?= h($r) ?></option><?php endforeach; ?></select></label><label>Phone<input name="guardian_phone" required maxlength="30" placeholder="+263 7X XXX XXXX"></label><label>Email <span class="optional">Optional</span><input type="email" name="guardian_email" maxlength="160"></label><label class="full-width">Home address <span class="optional">Optional</span><textarea name="address" rows="2" maxlength="1000"></textarea></label></div><p class="privacy-note">Applicant details are confidential and available to admission staff only. Record guardian consent after enrollment using the learner record’s approved privacy process.</p><div class="form-actions"><a class="outline-button" href="?page=admissions">Cancel</a><button class="primary-button">Register application</button></div></form></section><?php endif; ?>
<section class="panel learners-panel"><form class="list-toolbar" method="get"><input type="hidden" name="page" value="admissions"><div class="search-box"><span>⌕</span><input name="q" value="<?= h($q) ?>" placeholder="Search application, applicant or guardian"></div><div class="toolbar-right"><select name="status" class="select-control"><option value="">All statuses</option><?php foreach(['Submitted','Under Review','Waitlisted','Offered','Accepted','Declined','Enrolled'] as $s): ?><option <?= $filterStatus===$s?'selected':'' ?>><?= h($s) ?></option><?php endforeach; ?></select><select name="year" class="select-control"><option value="">All entry years</option><?php foreach($termYears as $year): ?><option value="<?= $year ?>" <?= $filterYear===$year?'selected':'' ?>><?= $year ?></option><?php endforeach; ?><option value="<?= $currentYear ?>" <?= $filterYear===$currentYear?'selected':'' ?>><?= $currentYear ?></option></select><button class="outline-button">Filter</button></div></form></section>
<section class="panel learners-panel"><div class="panel-heading"><div><h2>Applications</h2><p><?= count($applications) ?> records shown · maximum 200 per filter</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Applicant</th><th>Entry</th><th>Guardian contact</th><th>Application status</th><th>Review / enrollment</th></tr></thead><tbody><?php foreach($applications as $app): ?><tr><td><b><?= h($app['first_name'].' '.$app['last_name']) ?></b><br><span class="muted-cell"><?= h($app['application_code']) ?> · <?= $app['sex']==='F'?'Female':'Male' ?><?= $app['date_of_birth']?' · DOB '.h(date('d M Y',strtotime($app['date_of_birth']))):'' ?></span><?php if($app['previous_school']): ?><br><span class="muted-cell">Previous school: <?= h($app['previous_school']) ?></span><?php endif; ?></td><td>Form <?= (int)$app['intended_form'] ?> · <?= (int)$app['entry_year'] ?><?= $app['stream_preference']?' · '.h($app['stream_preference']):'' ?></td><td><?= h($app['guardian_name']) ?> (<?= h($app['guardian_relationship']) ?>)<br><?= h($app['guardian_phone']) ?><?= $app['guardian_email']?'<br>'.h($app['guardian_email']):'' ?></td><td><span class="status-pill"><?= h($app['status']) ?></span><?php if($app['offer_expires_on']): ?><br><span class="muted-cell">Offer expires <?= h(date('d M Y',strtotime($app['offer_expires_on']))) ?></span><?php endif; ?><?php if($app['student_id']): ?><br><a class="text-button" href="?page=students&id=<?= (int)$app['student_id'] ?>">Open learner record →</a><?php endif; ?><?php if($canReview&&!empty($history[$app['id']])): ?><details><summary>Status history</summary><?php foreach($history[$app['id']] as $h): ?><p><?= h(date('d M Y H:i',strtotime($h['created_at']))) ?> · <?= h($h['from_status']?:'New') ?> → <b><?= h($h['to_status']) ?></b><br><?= h($h['full_name']??'Former staff') ?>: <?= h($h['notes']??'') ?></p><?php endforeach; ?></details><?php endif; ?></td><td>
<?php $transitions=['Submitted'=>['Under Review','Waitlisted','Declined'],'Under Review'=>['Waitlisted','Offered','Declined'],'Waitlisted'=>['Under Review','Offered','Declined'],'Offered'=>['Under Review','Accepted','Declined'],'Accepted'=>['Declined']];$options=$transitions[$app['status']]??[];if($canReview&&$options): ?><details><summary>Record decision</summary><form method="post" action="actions/admission_review.php" class="compact-form"><?= csrf_field() ?><input type="hidden" name="application_id" value="<?= (int)$app['id'] ?>"><label>Decision<select name="to_status" class="admission-status-select"><?php foreach($options as $o): ?><option><?= h($o) ?></option><?php endforeach; ?></select></label><label class="offer-expiry-field" hidden>Offer expiry date<input type="date" name="offer_expires_on" min="<?= h(date('Y-m-d')) ?>"></label><label>Decision note<textarea name="notes" rows="2" maxlength="2000" minlength="5" required></textarea></label><button class="primary-button">Save decision</button></form></details><?php endif; ?>
<?php if($canReview&&$app['status']==='Accepted'&&!$app['student_id']): ?><details><summary>Enroll learner</summary><form method="post" action="actions/admission_enrol.php" class="compact-form"><?= csrf_field() ?><input type="hidden" name="application_id" value="<?= (int)$app['id'] ?>"><label>School admission number<input name="admission_no" maxlength="30" required placeholder="e.g. MVS-2026-001"></label><label>Entry term<select name="term_id" required><option value="">Select term</option><?php foreach($terms as $term): if((int)$term['academic_year']===(int)$app['entry_year']&&$term['ends_on']>=date('Y-m-d')): ?><option value="<?= (int)$term['id'] ?>"><?= h($term['name']) ?> · <?= (int)$term['academic_year'] ?><?php if($term['starts_on']>date('Y-m-d')): ?> · starts <?= h(date('d M Y',strtotime($term['starts_on']))) ?><?php endif; ?></option><?php endif; endforeach; ?></select></label><label>Allocated class stream<select name="stream" required><option value="">Select an existing class</option><?php foreach($classes as $class): if((int)$class['academic_year']===(int)$app['entry_year']&&(int)$class['form_level']===(int)$app['intended_form']): ?><option value="<?= h($class['stream']) ?>" <?= ($app['stream_preference']??'')===$class['stream']?'selected':'' ?>><?= h('Form '.$class['form_level'].$class['stream'].' · '.$class['academic_year']) ?></option><?php endif; endforeach; ?></select></label><button class="primary-button" onclick="return confirm('Create the learner and enrollment record from this accepted application?')">Create learner record</button></form></details><?php endif; ?>
</td></tr><?php endforeach; if(!$applications): ?><tr><td colspan="5" class="empty-cell">No applications match these filters.</td></tr><?php endif; ?></tbody></table></div></section>
<script>document.querySelectorAll('.admission-status-select').forEach(function(select){const form=select.closest('form'),field=form.querySelector('.offer-expiry-field'),date=field.querySelector('input');function update(){const offered=select.value==='Offered';field.hidden=!offered;date.required=offered}select.addEventListener('change',update);update()});</script>
